import { readFile, realpath } from "node:fs/promises"
import { dirname, isAbsolute, relative, resolve } from "node:path"
import { parseM71Json } from "../packages/neuvetra-database/src/m71-validation"
import {
  M80_HOSTED_INPUT_PROFILE,
  m80ExpectedHostedEvidence,
  m80HostedCanonicalJson,
  m80HostedSha256,
  type EvidencePin,
  type HostedPreparationInput,
  type M80HostedPreparationPlan,
} from "./m80-foundation-hosted-prepare-v2"
import {
  sealM80HostedIntent,
  validateM80HostedGate,
  validateM80HostedPlan,
  writeM80HostedEvidenceOnce,
  type M80HostedIntent,
  type M80HostedLoadedEvidence,
  type M80HostedPredecessorArtifacts,
  type M80HostedStage,
} from "./m80-foundation-hosted-once-v2"
import {
  M80_EXECUTOR_BUNDLE_PROFILE,
  validateM80ExecutorReview,
  type M80ExecutorArtifacts,
  type M80ExecutorFileBundle,
} from "./m80-foundation-executor"

const MAX_EVIDENCE_BYTES = 4_000_000
const SHA256 = /^[0-9a-f]{64}$/
const repoRoot = resolve(import.meta.dir, "..")

export interface M80StageBundleComposeInput {
  outputPath: string
  stage: M80HostedStage
  planPath: string
  gatePath: string
  intentPath: string
  executorReviewPath: string
  migration: M80PredecessorPaths | null
  admission: M80PredecessorPaths | null
}

export interface M80PredecessorPaths {
  intentPath: string
  observationPath: string
  outcomePath: string
}

export interface M80StageBundleComposeDependencies {
  readBytes?: (path: string) => Promise<Uint8Array>
  now?: Date
}

function safeInputPath(path: string): string {
  if (!path || isAbsolute(path) || path.includes("\\") || path.split("/").includes("..")) throw new Error("Evidence path must be a safe workspace-relative path.")
  return path
}

async function readWorkspaceBytes(path: string): Promise<Uint8Array> {
  safeInputPath(path)
  const root = await realpath(repoRoot), actual = await realpath(resolve(repoRoot, path)), inside = relative(root, actual)
  if (!inside || inside.startsWith("..") || isAbsolute(inside)) throw new Error("Evidence path escaped the workspace through a filesystem link.")
  return readFile(actual)
}

async function loadEvidence(path: string, readBytes: (path: string) => Promise<Uint8Array>): Promise<M80HostedLoadedEvidence> {
  safeInputPath(path)
  const bytes = await readBytes(path)
  if (bytes.byteLength < 2 || bytes.byteLength > MAX_EVIDENCE_BYTES) throw new Error(`Evidence size is outside the bundle composer bound for ${path}.`)
  return { value: parseM71Json(new TextDecoder().decode(bytes), MAX_EVIDENCE_BYTES), pin: { path, sha256: m80HostedSha256(bytes) } }
}

function exactPin(value: unknown, name: string): EvidencePin {
  if (!value || typeof value !== "object" || Array.isArray(value) || Object.getPrototypeOf(value) !== Object.prototype) throw new Error(`${name} must be an exact byte pin.`)
  const row = value as Record<string, unknown>
  if (Object.keys(row).sort().join("|") !== "path|sha256" || typeof row.path !== "string" || typeof row.sha256 !== "string" || !SHA256.test(row.sha256)) throw new Error(`${name} must be an exact byte pin.`)
  safeInputPath(row.path)
  return row as unknown as EvidencePin
}

function exactArtifactSha(value: unknown): string {
  return m80HostedSha256(`${JSON.stringify(value, null, 2)}\n`)
}

async function loadReferenced(value: unknown, name: string, readBytes: (path: string) => Promise<Uint8Array>): Promise<M80HostedLoadedEvidence> {
  const expected = exactPin(value, name), loaded = await loadEvidence(expected.path, readBytes)
  if (loaded.pin.sha256 !== expected.sha256) throw new Error(`${name} bytes changed.`)
  return loaded
}

async function loadGateEvidence(gate: unknown, readBytes: (path: string) => Promise<Uint8Array>): Promise<M80ExecutorArtifacts["gateEvidence"]> {
  const row = gate as Record<string, unknown>
  return {
    securityReview: await loadReferenced(row.securityReview, "gate security review", readBytes),
    integrationAcceptance: await loadReferenced(row.integrationAcceptance, "gate integration acceptance", readBytes),
    targetObservation: await loadReferenced(row.targetObservation, "gate target observation", readBytes),
  }
}

async function loadPredecessor(paths: M80PredecessorPaths | null, name: "migration" | "admission", readBytes: (path: string) => Promise<Uint8Array>): Promise<M80HostedPredecessorArtifacts | undefined> {
  if (paths === null) return undefined
  const intent = await loadEvidence(paths.intentPath, readBytes), observation = await loadEvidence(paths.observationPath, readBytes), outcome = await loadEvidence(paths.outcomePath, readBytes)
  const gatePin = exactPin((intent.value as Record<string, unknown>).gate, `${name} predecessor gate`), gate = await loadReferenced(gatePin, `${name} predecessor gate`, readBytes)
  return { intent: intent.value, intentPin: intent.pin, gate: gate.value, gatePin: gate.pin, gateEvidence: await loadGateEvidence(gate.value, readBytes), observation: observation.value, observationPin: observation.pin, outcome: outcome.value, outcomePin: outcome.pin }
}

async function loadPlanEvidence(plan: M80HostedPreparationPlan, readBytes: (path: string) => Promise<Uint8Array>): Promise<M80ExecutorArtifacts["planEvidence"]> {
  const { fixtureProfileId: _profile, fixtureVersion: _version, fixtureSha256: _fixture, ...admission } = plan.admission
  const input = { profile: M80_HOSTED_INPUT_PROFILE, operatorId: "/root", observedTarget: plan.target, publication: plan.publication, acceptedRuntime: { candidate: plan.pins.candidate, migration: plan.pins.migration, rootClosure: plan.pins.rootClosure }, backup: plan.backup, rehearsal: plan.rehearsal, admission } as HostedPreparationInput
  const rows: Array<[keyof M80ExecutorArtifacts["planEvidence"], EvidencePin, Parameters<typeof m80ExpectedHostedEvidence>[1]]> = [
    ["targetObservation", plan.pins.targetObservation, "target"],
    ["publicationReview", plan.pins.publicationReview, "publication"],
    ["integrationAcceptance", plan.pins.integrationAcceptance, "integration"],
    ["backupReceipt", plan.pins.backupReceipt, "backup"],
    ["restoreReceipt", plan.pins.restoreReceipt, "restore"],
    ["preservationReceipt", plan.pins.preservationReceipt, "preservation"],
    ["migrationRehearsalReceipt", plan.pins.migrationRehearsalReceipt, "rehearsal"],
    ["admissionObservation", plan.pins.admissionObservation, "admission"],
  ]
  const result = {} as M80ExecutorArtifacts["planEvidence"]
  for (const [name, expectedPin, kind] of rows) {
    const loaded = await loadReferenced(expectedPin, `plan evidence ${name}`, readBytes), expected = m80ExpectedHostedEvidence(input, kind)
    if (m80HostedCanonicalJson(loaded.value) !== m80HostedCanonicalJson(expected) || loaded.pin.sha256 !== exactArtifactSha(loaded.value)) throw new Error(`Typed plan evidence changed for ${name}.`)
    result[name] = loaded
  }
  return result
}

function predecessorPins(value: M80HostedPredecessorArtifacts | undefined): M80ExecutorFileBundle["migration"] {
  return value ? { intent: value.intentPin, observation: value.observationPin, outcome: value.outcomePin } : null
}

export function m80StageBundlePath(plan: Pick<M80HostedPreparationPlan, "operationScopeSha256">, stage: M80HostedStage): string {
  return `.superpowers/m80-foundation-executor-${plan.operationScopeSha256}-${stage}-bundle.json`
}

export async function composeM80StageBundle(input: M80StageBundleComposeInput, deps: M80StageBundleComposeDependencies = {}): Promise<M80ExecutorFileBundle> {
  if (!(["migration", "admission", "deployment"] as string[]).includes(input.stage)) throw new Error("Exact migration, admission or deployment stage required.")
  const readBytes = deps.readBytes ?? readWorkspaceBytes, now = deps.now ?? new Date()
  const planLoaded = await loadEvidence(input.planPath, readBytes), plan = validateM80HostedPlan(planLoaded.value, now)
  const gateLoaded = await loadEvidence(input.gatePath, readBytes), gateEvidence = await loadGateEvidence(gateLoaded.value, readBytes)
  validateM80HostedGate(gateLoaded.value, plan, planLoaded.pin, input.stage, gateEvidence, now)
  const intentLoaded = await loadEvidence(input.intentPath, readBytes), intent = intentLoaded.value as M80HostedIntent
  if (intent.stage !== input.stage || Date.parse(intent.createdAt) > now.getTime()) throw new Error("Sealed intent stage or chronology differs from the requested bundle.")
  const migration = await loadPredecessor(input.migration, "migration", readBytes), admission = await loadPredecessor(input.admission, "admission", readBytes)
  const rebuilt = sealM80HostedIntent({ plan, planPin: planLoaded.pin, gate: gateLoaded.value, gatePin: gateLoaded.pin, gateEvidence, stage: input.stage, migration, admission, now: new Date(intent.createdAt) })
  if (intentLoaded.pin.sha256 !== exactArtifactSha(intentLoaded.value) || m80HostedCanonicalJson(rebuilt) !== m80HostedCanonicalJson(intentLoaded.value)) throw new Error("Supplied intent is not the exact reconstructed sealed intent.")
  const executorReview = await loadEvidence(input.executorReviewPath, readBytes)
  await validateM80ExecutorReview(executorReview.pin, readBytes)
  const planEvidence = await loadPlanEvidence(plan, readBytes)
  const expectedOutput = m80StageBundlePath(plan, input.stage)
  if (input.outputPath !== expectedOutput || dirname(input.outputPath) !== ".superpowers") throw new Error(`Output path must be the deterministic stage bundle path ${expectedOutput}.`)
  return {
    profile: M80_EXECUTOR_BUNDLE_PROFILE,
    stage: input.stage,
    plan: planLoaded.pin,
    gate: gateLoaded.pin,
    intent: intentLoaded.pin,
    executorReview: executorReview.pin,
    planEvidence: Object.fromEntries(Object.entries(planEvidence).map(([name, item]) => [name, item.pin])) as M80ExecutorFileBundle["planEvidence"],
    migration: predecessorPins(migration),
    admission: predecessorPins(admission),
  }
}

function pathsFromArgs(values: string[], offset: number): M80PredecessorPaths | null {
  const triplet = values.slice(offset, offset + 3)
  if (triplet.length !== 3) throw new Error("Each predecessor must supply exactly three paths or three '-' placeholders.")
  if (triplet.every(value => value === "-")) return null
  if (triplet.some(value => value === "-")) throw new Error("A predecessor requires its complete intent, observation and outcome paths.")
  return { intentPath: triplet[0]!, observationPath: triplet[1]!, outcomePath: triplet[2]! }
}

async function runSelfCheck(): Promise<void> {
  const fixture = await import("../evaluations/research-qa/m80-executor-independent-20260924-candidate9-fixture")
  const artifacts = await fixture.artifacts("deployment"), sources = new Map<string, Uint8Array>(), encode = (value: unknown) => new TextEncoder().encode(`${JSON.stringify(value, null, 2)}\n`)
  const put = (item: M80HostedLoadedEvidence) => sources.set(item.pin.path, encode(item.value))
  put({ value: artifacts.plan, pin: artifacts.planPin }); put({ value: artifacts.gate, pin: artifacts.gatePin }); put({ value: artifacts.intent, pin: artifacts.intentPin })
  Object.values(artifacts.gateEvidence).forEach(put); Object.values(artifacts.planEvidence).forEach(put)
  for (const chain of [artifacts.migration, artifacts.admission]) if (chain) { put({ value: chain.intent, pin: chain.intentPin }); put({ value: chain.gate, pin: chain.gatePin }); Object.values(chain.gateEvidence).forEach(put); put({ value: chain.observation, pin: chain.observationPin }); put({ value: chain.outcome, pin: chain.outcomePin }) }
  const fixtureReader = fixture.reviewReaders.get(artifacts)!, readBytes = async (path: string) => sources.get(path) ?? fixtureReader(path)
  const input: M80StageBundleComposeInput = { outputPath: m80StageBundlePath(artifacts.plan as M80HostedPreparationPlan, "deployment"), stage: "deployment", planPath: artifacts.planPin.path, gatePath: artifacts.gatePin.path, intentPath: artifacts.intentPin.path, executorReviewPath: artifacts.executorReview.path, migration: { intentPath: artifacts.migration!.intentPin.path, observationPath: artifacts.migration!.observationPin.path, outcomePath: artifacts.migration!.outcomePin.path }, admission: { intentPath: artifacts.admission!.intentPin.path, observationPath: artifacts.admission!.observationPin.path, outcomePath: artifacts.admission!.outcomePin.path } }
  const bundle = await composeM80StageBundle(input, { readBytes, now: fixture.NOW })
  if (bundle.stage !== "deployment" || !bundle.migration || !bundle.admission) throw new Error("Positive bundle fixture failed.")
  let refused = false
  try { await composeM80StageBundle({ ...input, admission: { ...input.admission!, outcomePath: input.migration!.outcomePath } }, { readBytes, now: fixture.NOW }) }
  catch { refused = true }
  if (!refused) throw new Error("Foreign predecessor outcome fixture was accepted.")
  console.log(JSON.stringify({ status: "m80_stage_bundle_compose_self_check_pass", positive: true, foreignPredecessorRefused: true }))
}

if (import.meta.main) {
  const [mode, ...args] = process.argv.slice(2)
  if (mode === "self-check") await runSelfCheck()
  else if (mode === "compose") {
    if (args.length !== 12) throw new Error("Usage: ... compose <output> <stage> <plan> <gate> <sealed-intent> <executor-review> <migration-intent|-> <migration-observation|-> <migration-outcome|-> <admission-intent|-> <admission-observation|-> <admission-outcome|->")
    const [outputPath, stage, planPath, gatePath, intentPath, executorReviewPath] = args
    const input: M80StageBundleComposeInput = { outputPath: outputPath!, stage: stage as M80HostedStage, planPath: planPath!, gatePath: gatePath!, intentPath: intentPath!, executorReviewPath: executorReviewPath!, migration: pathsFromArgs(args, 6), admission: pathsFromArgs(args, 9) }
    const bundle = await composeM80StageBundle(input)
    const absolute = resolve(repoRoot, input.outputPath), parent = await realpath(dirname(absolute)), expectedParent = await realpath(resolve(repoRoot, ".superpowers"))
    if (parent.toLowerCase() !== expectedParent.toLowerCase()) throw new Error("Bundle output parent escaped the fixed .superpowers directory.")
    await writeM80HostedEvidenceOnce(absolute, bundle)
    const bytes = await readFile(absolute)
    console.log(JSON.stringify({ status: "m80_stage_bundle_composed_no_action_executed", stage: input.stage, path: input.outputPath, sha256: m80HostedSha256(bytes) }))
  } else throw new Error("Use compose or self-check. This helper only validates and writes one secret-free offline bundle.")
}
